fn wyr_modify_default_components(item: &str, components: &mut serde_json::Map<String, serde_json::Value>) { if item=="minecraft:leather" { components.insert("minecraft:food".into(),serde_json::json!({"nutrition":2,"saturation":0.1})); components.insert("minecraft:consumable".into(),serde_json::json!({"consume_seconds":1.6,"animation":"eat","sound":"minecraft:entity.generic.eat"})); } }
